def transform(grid):
    bg = grid[0][0]
    objects = []
    for c in {v for row in grid for v in row if v != bg}:
        cells = [(r,j) for r,row in enumerate(grid) for j,v in enumerate(row) if v == c]
        r0,r1 = min(r for r,j in cells),max(r for r,j in cells)
        c0,c1 = min(j for r,j in cells),max(j for r,j in cells)
        holes = {(r,j) for r in range(r0,r1+1) for j in range(c0,c1+1) if grid[r][j] == bg}
        comps = []
        while holes:
            seed = holes.pop()
            stack,comp = [seed],[seed]
            while stack:
                r,j = stack.pop()
                for q in ((r-1,j),(r+1,j),(r,j-1),(r,j+1)):
                    if q in holes:
                        holes.remove(q); stack.append(q); comp.append(q)
            comps.append(comp)
        area = (r1-r0+1)*(c1-c0+1)
        objects.append((c,r0,r1,c0,c1,area,comps))
    p = min((o for o in objects if len(o[6]) >= 2),key=lambda o:o[5])
    solids = [o for o in objects if not o[6]]
    def shape(cells):
        a,b = min(r for r,j in cells),min(j for r,j in cells)
        return frozenset((r-a,j-b) for r,j in cells)
    out = [[p[0] if grid[r][j] == p[0] else bg for j in range(p[3],p[4]+1)] for r in range(p[1],p[2]+1)]
    for comp in p[6]:
        matches = [o for o in solids if shape(o[6] and [(r,j) for r in range(o[1],o[2]+1) for j in range(o[3],o[4]+1)] or []) == shape(comp)]
        if not matches:
            matches = [o for o in solids if (o[2]-o[1]+1,o[4]-o[3]+1) == (max(r for r,j in comp)-min(r for r,j in comp)+1,max(j for r,j in comp)-min(j for r,j in comp)+1)]
        fill = min(matches or solids,key=lambda o:o[5])[0]
        for r,j in comp:
            out[r-p[1]][j-p[3]] = fill
    return out
